'use strict';
let evidenceDbPromise,ocrBusy=false,ocrWorker=null,evidenceOcrDraft=null;
const evidenceUrls=new Map();
function evidenceDB(){if(!evidenceDbPromise)evidenceDbPromise=new Promise((resolve,reject)=>{const req=indexedDB.open('jimu-evidence-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('images',{keyPath:'id'});req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('本地图片存储不可用，请检查浏览器存储权限。'));});return evidenceDbPromise;}
async function evidenceStore(method,...args){const db=await evidenceDB();return new Promise((resolve,reject)=>{const tx=db.transaction('images',['get','getAll'].includes(method)?'readonly':'readwrite'),req=tx.objectStore('images')[method](...args);tx.oncomplete=()=>resolve(req.result);tx.onerror=()=>reject(Error('图片保存失败，浏览器存储可能已满。'));tx.onabort=()=>reject(Error('图片存储操作未完成。'));});}
function evidencePanel(p){return `<section class="evidence-module" data-project="${p.id}"><div class="section-head"><h2>${icon('file',16)} 后台截图录入</h2>${pill('本地保存','gray')}</div><p class="copy">当前未连接平台后台授权。视频链接用于对应作品；后台数据请上传截图，或继续手动填写。</p><div class="evidence-drop" id="evidence-drop" tabindex="0" role="group" aria-label="拖入或粘贴后台截图"><span class="evidence-drop-icon">${icon('file',24)}</span><div><b>拖入截图，或在此粘贴图片</b><p>支持 PNG / JPG / WebP，最多 8 张，每张不超过 8 MB。</p></div><label class="btn soft evidence-picker">${icon('plus',14)} 选择截图<input type="file" id="evidence-input" accept="image/png,image/jpeg,image/webp" multiple aria-label="上传后台截图"></label></div><div id="evidence-status" role="status" aria-live="polite" class="copy"></div><div id="evidence-gallery" class="evidence-gallery">${(p.metricScreenshots||[]).map(r=>evidenceThumb(r,p.id)).join('')}</div><p class="evidence-help">截图保存在当前浏览器，刷新后保留。文字识别在本地运行；先核对，再填入表单，不会自动覆盖原数据。截图时间和统计窗口仍需你确认。</p><div class="actions"><a class="text-btn" href="https://creator.douyin.com/" target="_blank" rel="noopener noreferrer">打开抖音创作者中心 ↗</a><a class="text-btn" href="https://creator.xiaohongshu.com/" target="_blank" rel="noopener noreferrer">打开小红书创作者中心 ↗</a></div></section>`;}
function evidenceThumb(r,projectId,readonly=false){return `<article class="evidence-thumb" data-image-id="${r.id}"><button type="button" class="evidence-image-button" data-action="evidence-preview" data-id="${projectId}" data-image="${r.id}" aria-label="查看截图 ${esc(r.name)}"><img data-evidence-image="${r.id}" alt="${esc(r.name)}" loading="lazy"><span data-image-loading="${r.id}">正在读取截图…</span></button><b title="${esc(r.name)}">${esc(r.name)}</b><small>${r.width} × ${r.height} · 上传 ${date(r.addedAt,true)}</small><div class="actions">${!readonly?`<button type="button" class="btn small soft" data-action="evidence-ocr" data-id="${projectId}" data-image="${r.id}" ${ocrBusy?'disabled':''}>识别数据</button><button type="button" class="text-btn" data-action="evidence-remove" data-id="${projectId}" data-image="${r.id}">移除</button>`:btn('查看截图','evidence-preview',projectId,'small').replace('data-id=',`data-image="${r.id}" data-id=`)}</div></article>`;}
function evidenceSummary(p){if(!p.metricScreenshots?.length)return '';return `<details class="evidence-readonly"><summary class="copy">${icon('file',14)} 查看数据截图依据 · ${p.metricScreenshots.length} 张</summary><div class="evidence-gallery">${p.metricScreenshots.map(r=>evidenceThumb(r,p.id,true)).join('')}</div></details>`;}
function captureMetricDraft(){const f=$('#publish-form');if(!f)return;const p=currentProject(f.dataset.id),d={};for(const [k,v]of new FormData(f))if(['platform','publishedAt','publishUrl','window','plays','completion','likes','comments','saves','shares','follows','source','collectedAt'].includes(k)&&typeof v==='string')d[k]=v;p.metricEntryDraft=d;persist();}
async function evidenceUrl(id){if(evidenceUrls.has(id))return evidenceUrls.get(id);const record=await evidenceStore('get',id);if(!record)return null;const url=URL.createObjectURL(record.blob);evidenceUrls.set(id,url);return url;}
async function hydrateEvidence(){const f=$('#publish-form');if(f){const p=currentProject(f.dataset.id);for(const [key,value]of Object.entries(p.metricEntryDraft||{}))if(f.elements[key])f.elements[key].value=value;}for(const img of document.querySelectorAll('img[data-evidence-image]')){const id=img.dataset.evidenceImage;try{const url=await evidenceUrl(id);if(!img.isConnected)continue;if(url){img.src=url;img.hidden=false;img.closest('.evidence-image-button')?.querySelector('span')?.remove();}else{img.hidden=true;const t=img.closest('.evidence-image-button')?.querySelector('span');if(t)t.textContent='附件缺失，请重新上传原图';}}catch(e){const t=img.closest('.evidence-image-button')?.querySelector('span');if(t)t.textContent=e.message;}}}
async function inspectImage(file){if(!JimuEvidence.types.includes(file.type))throw Error('请使用 PNG、JPG 或 WebP 截图。');if(file.size<=0||file.size>JimuEvidence.MAX_FILE)throw Error('每张截图需在 8 MB 以内。');const img=await createImageBitmap(file).catch(()=>{throw Error('无法读取图片，请重新导出有效截图。');});const size={width:img.width,height:img.height};img.close();if(size.width*size.height>40000000)throw Error('截图尺寸过大，请分成多张截图后上传。');return size;}
async function addEvidence(files,projectId){const p=currentProject(projectId);if(p.stage!==5)throw Error('请先进入数据录入页面。');captureMetricDraft();let count=0;for(const file of files){if((p.metricScreenshots||[]).length>=JimuEvidence.MAX_COUNT)throw Error('当前视频最多保存 8 张截图。');const size=await inspectImage(file),all=await evidenceStore('getAll');if(all.reduce((n,x)=>n+x.blob.size,0)+file.size>JimuEvidence.MAX_TOTAL)throw Error('本地截图总量已达 32 MB，请先导出备份并移除不再需要的截图。');const ref={id:C.id(),name:file.name||'粘贴截图.png',type:file.type,size:file.size,...size,addedAt:C.iso()};await evidenceStore('put',{id:ref.id,blob:file});p.metricScreenshots=[...(p.metricScreenshots||[]),ref];if(!persist()){p.metricScreenshots=p.metricScreenshots.filter(x=>x.id!==ref.id);await evidenceStore('delete',ref.id);throw Error('图片记录未保存成功，请检查浏览器存储。');}count++;}if(getRoute()[1]===p.id){render();}toast(`已保存 ${count} 张后台截图，可识别或对照填写`);}
function evidenceProgress(text){const s=$('#evidence-status');if(s)s.textContent=text;}
function loadOcrScript(){if(window.Tesseract)return Promise.resolve();return new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=new URL('vendor/ocr/tesseract.min.js',document.baseURI).href;script.onload=resolve;script.onerror=()=>{script.remove();reject(Error('本地识别组件加载失败，可继续对照截图手动录入。'));};document.head.append(script);});}
async function recognizeEvidence(projectId,imageId){if(ocrBusy)throw Error('一张截图正在识别，请稍等。');captureMetricDraft();const record=await evidenceStore('get',imageId);if(!record)throw Error('截图文件缺失，请重新上传。');if(record.blob.size>JimuEvidence.MAX_FILE)throw Error('截图过大，无法识别。');ocrBusy=true;document.querySelectorAll('[data-action=evidence-ocr]').forEach(el=>el.disabled=true);evidenceProgress('正在启动本地文字识别，首次加载可能需要一点时间…');let timeout;
try{await loadOcrScript();const base=new URL('vendor/ocr/',document.baseURI).href;const workerPromise=Tesseract.createWorker('chi_sim+eng',1,{workerPath:base+'worker.min.js',corePath:base,langPath:base,workerBlobURL:false,logger:m=>{if(m.status==='recognizing text')evidenceProgress('正在识别截图文字 '+Math.round(m.progress*100)+'%');},errorHandler:()=>{}});ocrWorker=await workerPromise;await ocrWorker.setParameters({preserve_interword_spaces:'1'});const result=await Promise.race([ocrWorker.recognize(record.blob),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(Error('识别耗时较长，请使用更清晰、更小的单页截图，或对照手动录入。')),90000);})]);const text=(result.data.text||'').slice(0,60000);const p=currentProject(projectId),ref=p.metricScreenshots?.find(r=>r.id===imageId);if(!ref)return;ref.ocrText=text;ref.ocrAt=C.iso();persist();evidenceProgress('识别完成，请核对文字与数据。');if(getRoute()[0]==='project'&&getRoute()[1]===projectId&&$('#publish-form'))openOcrReview(p,ref,text);else toast('截图识别已完成，回到数据录入页可查看结果。');
}catch(e){evidenceProgress('识别未完成。你仍可放大截图，对照手动录入。');throw e;}finally{clearTimeout(timeout);if(ocrWorker){await ocrWorker.terminate().catch(()=>{});ocrWorker=null;}ocrBusy=false;document.querySelectorAll('[data-action=evidence-ocr]').forEach(el=>el.disabled=false);}}
function openOcrReview(p,ref,text){evidenceOcrDraft={projectId:p.id,imageId:ref.id,text,rows:JimuEvidence.parse(text)};const f=$('#publish-form');modal('核对截图数据，再填入',`<div class="ocr-review-grid"><div class="ocr-source-image"><img id="ocr-reference-image" alt="${esc(ref.name)}"><p class="copy">${esc(ref.name)} · 原图可滚动查看</p></div><form id="ocr-review-form"><p class="copy">文字识别可能出错。缺失、冲突和多列不明确的数值不会自动猜测；可对照原图手动填写。不会从截图推断采集时间或统计窗口。</p><details><summary class="copy">查看 / 修正识别文字</summary><label style="margin-top:12px">识别文字<textarea id="ocr-raw-text" rows="8">${esc(text)}</textarea></label>${btn('根据修正文字重新提取','evidence-reparse','','small')}</details><div id="ocr-candidates">${ocrCandidateRows(evidenceOcrDraft.rows,f)}</div><label class="checkrow"><input type="checkbox" name="verified" required><span>我已核对数值、视频归属与统计窗口；仅填入勾选字段。</span></label><button type="submit" class="btn primary" style="margin-top:16px">确认填入所选字段</button><p class="copy" style="margin-top:12px">填入后还需保存录入数据，才会进入复盘。</p></form></div>`);$('.modal').classList.add('ocr-modal');evidenceUrl(ref.id).then(url=>{const img=$('#ocr-reference-image');if(img&&url)img.src=url;});}
function ocrCandidateRows(rows,f){return rows.map(r=>`<div class="ocr-candidate"><label class="ocr-choice"><input type="checkbox" name="use-${r.key}"><span>${r.label}</span></label><label><span class="visually-hidden">${r.label}候选值</span><input name="value-${r.key}" type="number" min="0" ${r.percent?'max="100" step="0.01"':'step="1"'} value="${r.value??''}" placeholder="未识别，请对照填写"></label><div class="ocr-evidence">${r.conflict?'检测到不同数值，需人工选择。':r.evidence?esc(r.evidence):'无明确标签与数值对应。'}${r.approx?' · 万 / 千缩写按近似值换算':''}<br>表单原值：${esc(f?.elements[r.key]?.value||'未填')}</div></div>`).join('');}
async function packEvidenceBackup(){const backup=JSON.parse(JSON.stringify(S));backup.screenshotFiles=[];const ids=[...new Set(backup.projects.flatMap(p=>(p.metricScreenshots||[]).map(r=>r.id)))];for(const id of ids){const record=await evidenceStore('get',id);if(!record)continue;const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(record.blob);});backup.screenshotFiles.push({id,data});}return backup;}
async function validateEvidenceBackup(backup){if(backup.screenshotFiles===undefined)return;const refs=new Map(backup.projects.flatMap(p=>(p.metricScreenshots||[]).map(r=>[r.id,r])));if(!Array.isArray(backup.screenshotFiles))throw Error('截图备份格式不正确。');let total=0;const seen=new Set();for(const f of backup.screenshotFiles){if(!f||seen.has(f.id)||!refs.has(f.id)||typeof f.data!=='string'||!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(f.data))throw Error('截图备份包含无效图片。');seen.add(f.id);const ref=refs.get(f.id),blob=dataToBlob(f.data);if(blob.size!==ref.size||blob.type!==ref.type)throw Error('截图备份与附件记录不匹配。');const size=await inspectImage(blob);if(size.width!==ref.width||size.height!==ref.height)throw Error('截图尺寸与记录不匹配。');total+=blob.size;if(total>JimuEvidence.MAX_TOTAL)throw Error('截图备份总量超过 32 MB。');}}
function dataToBlob(data){const [meta,base64]=data.split(','),raw=atob(base64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:meta.slice(5).split(';')[0]});}
async function restoreEvidenceBackup(backup){await validateEvidenceBackup(backup);const files=backup.screenshotFiles||[];if(files.length){const db=await evidenceDB();await new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');for(const f of files)tx.objectStore('images').put({id:f.id,blob:dataToBlob(f.data)});tx.oncomplete=resolve;tx.onerror=()=>reject(Error('截图恢复失败，未替换业务数据。'));tx.onabort=()=>reject(Error('截图恢复中断，未替换业务数据。'));});}for(const url of evidenceUrls.values())URL.revokeObjectURL(url);evidenceUrls.clear();const clean={...backup};delete clean.screenshotFiles;return clean;}
document.addEventListener('change',async e=>{if(e.target.id!=='evidence-input')return;const id=$('#publish-form')?.dataset.id;if(!id)return;try{await addEvidence([...e.target.files],id);}catch(err){toast(err.message,true);if(getRoute()[1]===id)render();}});
document.addEventListener('paste',async e=>{const f=$('#publish-form');if(!f)return;const files=[...(e.clipboardData?.items||[])].filter(x=>x.kind==='file'&&x.type.startsWith('image/')).map(x=>x.getAsFile());if(!files.length)return;e.preventDefault();try{await addEvidence(files,f.dataset.id);}catch(err){toast(err.message,true);}});
document.addEventListener('dragover',e=>{const drop=e.target.closest('#evidence-drop');if(drop){e.preventDefault();drop.classList.add('dragging');}});
document.addEventListener('dragleave',e=>{e.target.closest('#evidence-drop')?.classList.remove('dragging');});
document.addEventListener('drop',async e=>{const drop=e.target.closest('#evidence-drop');if(!drop)return;e.preventDefault();drop.classList.remove('dragging');try{await addEvidence([...e.dataTransfer.files],$('#publish-form').dataset.id);}catch(err){toast(err.message,true);}});
document.addEventListener('input',e=>{if(e.target.closest('#publish-form')&&e.target.name)captureMetricDraft();});
document.addEventListener('change',e=>{if(e.target.closest('#publish-form')&&e.target.name)captureMetricDraft();});
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el||!el.dataset.action.startsWith('evidence-'))return;const {action,id,image:imgId}=el.dataset;try{
if(action==='evidence-preview'){const p=currentProject(id),r=p.metricScreenshots.find(r=>r.id===imgId),url=await evidenceUrl(imgId);if(!url)throw Error('图片附件缺失，请重新上传。');modal('后台截图 · '+esc(r.name),`<div class="evidence-full"><img src="${esc(url)}" alt="${esc(r.name)}"></div><p class="copy">上传时间：${date(r.addedAt,true)}。上传时间不等于截图中的数据采集时间。</p>`);$('.modal').classList.add('evidence-view-modal');return;}
if(action==='evidence-remove'){captureMetricDraft();const p=currentProject(id);confirmModal('移除这张截图','仅移除这张后台截图，已录入的数值保持不变。','evidence-confirm-remove',id,'确认移除');$('.modal [data-action=evidence-confirm-remove]').dataset.image=imgId;return;}
if(action==='evidence-confirm-remove'){const p=currentProject(id),previous=p.metricScreenshots;p.metricScreenshots=previous.filter(r=>r.id!==imgId);if(!persist()){p.metricScreenshots=previous;return;}await evidenceStore('delete',imgId);if(evidenceUrls.has(imgId))URL.revokeObjectURL(evidenceUrls.get(imgId));evidenceUrls.delete(imgId);closeModal();render();toast('截图已移除');return;}
if(action==='evidence-ocr'){const p=currentProject(id),ref=p.metricScreenshots.find(r=>r.id===imgId);if(ref?.ocrText&&!e.ctrlKey&&!e.metaKey){captureMetricDraft();openOcrReview(p,ref,ref.ocrText);return;}await recognizeEvidence(id,imgId);return;}
if(action==='evidence-reparse'){evidenceOcrDraft.text=$('#ocr-raw-text').value;evidenceOcrDraft.rows=JimuEvidence.parse(evidenceOcrDraft.text);$('#ocr-candidates').innerHTML=ocrCandidateRows(evidenceOcrDraft.rows,$('#publish-form'));$('#ocr-review-form [name=verified]').checked=false;}
}catch(err){toast(err.message||'截图操作未完成，请重试。',true);}});
document.addEventListener('submit',e=>{if(e.target.id!=='ocr-review-form')return;e.preventDefault();try{const d=validForm(e.target),draft=evidenceOcrDraft,f=$('#publish-form');if(!f||f.dataset.id!==draft.projectId)throw Error('请回到对应视频的数据录入页。');const selected=JimuEvidence.fields.filter(r=>d['use-'+r.key]==='on');if(!selected.length)throw Error('请勾选至少一个已经核对的字段。');if(d.verified!=='on')throw Error('请先核对视频与统计窗口。');for(const r of selected){const raw=d['value-'+r.key],n=Number(raw);if(!raw.trim()||!Number.isFinite(n)||n<0||(r.percent?n>100:!Number.isInteger(n)))throw Error(r.label+'数值不正确。');}for(const r of selected)f.elements[r.key].value=d['value-'+r.key];f.elements.source.value=f.elements.platform.value+'后台截图（本地识别，人工核对）';captureMetricDraft();const p=currentProject(draft.projectId);p.metricEvidenceAudit={imageId:draft.imageId,checkedAt:C.iso(),fields:selected.map(x=>x.key)};persist();closeModal();toast('已填入并保存为草稿，请核对后保存录入数据');}catch(err){toast(err.message,true);}});
